from pypdf import PdfReader

reader = PdfReader('/root/sc100-blank.pdf')
if reader.is_encrypted:
    reader.decrypt('')

def print_field_names(field_obj, depth=0):
    field_obj = field_obj.get_object() if hasattr(field_obj, 'get_object') else field_obj

    field_name = field_obj.get("/T")
    if field_name:
        try:
            if hasattr(field_name, 'original_bytes'):
                name_str = field_name.original_bytes.decode('latin-1').strip('()')
            else:
                name_str = str(field_name).strip('()')
            print(f"{'  ' * depth}{name_str}")
        except:
            pass

    if field_obj.get('/Kids'):
        for kid in field_obj.get('/Kids'):
            print_field_names(kid, depth + 1)

if reader.root_object.get("/AcroForm"):
    fields = reader.root_object["/AcroForm"]["/Fields"]
    for field in fields:
        print_field_names(field)

